import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.cyF4XceO.js";const m=JSON.parse('{"title":"0003 — SpaceID is an opaque portable scope identity","description":"","frontmatter":{},"headers":[],"relativePath":"spec/decisions/0003-space-id-is-an-opaque-portable-scope-identity.md","filePath":"spec/decisions/0003-space-id-is-an-opaque-portable-scope-identity.md"}'),n={name:"spec/decisions/0003-space-id-is-an-opaque-portable-scope-identity.md"};function s(r,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="_0003-—-spaceid-is-an-opaque-portable-scope-identity" tabindex="-1">0003 — SpaceID is an opaque portable scope identity <a class="header-anchor" href="#_0003-—-spaceid-is-an-opaque-portable-scope-identity" aria-label="Permalink to &quot;0003 — SpaceID is an opaque portable scope identity&quot;">​</a></h1><ul><li>Status: accepted</li><li>Date: 2026-07-29</li><li>Owners: Takoform maintainers</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>metadata.space</code> scopes portable Resources and participates in exact Form queries, Interface reads, idempotency scope, Terraform/OpenTofu configuration, state, and import identifiers. The host wire schema previously constrained only its length, while clients and provider paths sometimes used <code>strings.TrimSpace</code>. That made the same identity vulnerable to different interpretation across runtimes.</p><p>Resource <code>metadata.name</code> has a separate lowercase URL-safe <code>PatternName</code> grammar. Reusing it for Space would make human or externally assigned scope identities unnecessarily restrictive and would conflate two domain concepts.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>SpaceID</code> is a distinct, case-sensitive opaque string. It is valid UTF-8 and contains 1 through 255 Unicode code points. It contains no C0 or C1 control code point and no <code>/</code>. Its first and last code points are neither Unicode <code>White_Space</code> nor <code>U+FEFF</code>.</p><p>Embedded non-control whitespace is valid data. Clients, hosts, and provider paths preserve the exact decoded code-point sequence without trimming, normalization, or case folding. The same validator governs Resource bodies, query parameters, provider defaults and overrides, Interface selectors, state, and the <code>SPACE/NAME</code> import form.</p><p>The normative JSON Schema uses explicit code-point sets. The Go client mirrors those sets rather than delegating their definition to runtime-specific trim behavior.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li><code>Prod</code>, <code>prod</code>, and <code>Prod North</code> are three exact values.</li><li><code>metadata.name</code> continues to use <code>PatternName</code>; it is not a Space validator.</li><li>Invalid Space values fail before an HTTP host operation.</li><li>Provider environment defaults are validated after selection and before host discovery.</li><li>Terraform/OpenTofu state and URL query decoding retain embedded whitespace exactly.</li><li><code>/</code> cannot be part of <code>SpaceID</code>, so <code>SPACE/NAME</code> import parsing is unambiguous.</li><li>Tightening the current <code>v1alpha1</code> contract is recorded and its public schema digest must be re-pinned before publication.</li></ul><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to &quot;Rejected alternatives&quot;">​</a></h2><ul><li><strong>Reuse Resource <code>PatternName</code>.</strong> Rejected because Space is an opaque scope identity, not a lowercase portable Resource name.</li><li><strong>Trim values at each input boundary.</strong> Rejected because trimming silently aliases distinct caller inputs and makes state or idempotency identity runtime-dependent.</li><li><strong>Apply Unicode normalization or case folding.</strong> Rejected because the host API promises exact opaque identity rather than a human-name comparison algorithm.</li><li><strong>Allow <code>/</code> and escape the import separator.</strong> Rejected because it adds a second import grammar for no portable identity benefit.</li></ul>',13)])])}const h=a(n,[["render",s]]);export{m as __pageData,h as default};
